import {ToolRegistry} from './registry.js';
import {setLogger} from '../../shared/logger.js';

describe('ToolRegistry', () => {
  afterEach(() => {
    setLogger(undefined);
  });

  it('throws synchronously from register naming the tool when a static inputSchema is invalid', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {
          name: 'weather_lookup',
          description: 'Look up weather for a city',
          inputSchema: {
            type: 'object',
            properties: {location: {type: 'invalid-json-schema-type'}},
          },
        },
        async () => 'sunny'
      )
    ).toThrow(/weather_lookup/);
  });

  it('rejects invalid input in execute with field paths and constraints while omitting values from result and logs', async () => {
    const emittedLogs: string[] = [];
    const recordLog = (category: string, message: string, fields?: Record<string, unknown>) => {
      emittedLogs.push(JSON.stringify({category, message, fields}));
    };
    setLogger({debug: recordLog, info: recordLog, warn: recordLog, error: recordLog});

    const registry = new ToolRegistry();
    let invocations = 0;
    registry.register(
      {
        name: 'patient_record',
        description: 'Fetch patient record',
        inputSchema: {
          type: 'object',
          properties: {
            department: {type: 'string'},
            nationalId: {type: 'string'},
          },
          required: ['department', 'nationalId'],
        },
      },
      async () => {
        invocations += 1;
        return 'record';
      }
    );

    const response = await registry.execute('patient_record', {nationalId: 987654321});
    const combinedLogs = emittedLogs.join('\n');

    expect({
      invocations,
      namesMissingField: response.result.includes('department') && /required/i.test(response.result),
      namesWrongTypeField: response.result.includes('nationalId') && response.result.includes('string'),
      logsFailurePath: combinedLogs.includes('department') && combinedLogs.includes('nationalId'),
      echoesSecretInResult: response.result.includes('987654321'),
      echoesSecretInLogs: combinedLogs.includes('987654321'),
    }).toEqual({
      invocations: 0,
      namesMissingField: true,
      namesWrongTypeField: true,
      logsFailurePath: true,
      echoesSecretInResult: false,
      echoesSecretInLogs: false,
    });
  });
});

