function validateToolInput(
  toolName: string,
  validator: ValidateFunction | undefined,
  input: Record<string, unknown>
): ToolResponse | undefined {
  if (!validator) return undefined;
  if (validator(input)) return undefined;
  const failures = (validator.errors ?? []).map(formatValidationError);
  const summary = failures.length > 0 ? failures.join('; ') : 'input failed schema validation';
  log.warn('tool', 'input validation failed', {name: toolName, failures});
  return {result: `Invalid input for tool "${toolName}": ${summary}`};
}

function formatValidationError(error: ErrorObject): string {
  const path = validationFieldPath(error);
  const constraint = validationConstraint(error);
  return path ? `${path}: ${constraint}` : constraint;
}

function validationFieldPath(error: ErrorObject): string {
  const pointer = error.instancePath;
  const trimmed = pointer.startsWith('/') ? pointer.slice(1) : pointer;
  const basePath = trimmed.replace(/\//g, '.');
  const params = error.params as Record<string, unknown>;
  const missing = typeof params.missingProperty === 'string' ? params.missingProperty : undefined;
  if (!missing) return basePath;
  return basePath ? `${basePath}.${missing}` : missing;
}

function validationConstraint(error: ErrorObject): string {
  const baseMessage = error.message ?? `failed "${error.keyword}" constraint`;
  const params = error.params as Record<string, unknown>;
  if (error.keyword === 'enum' && Array.isArray(params.allowedValues)) {
    const allowed = params.allowedValues.map(entry => String(entry)).join(', ');
    return `${baseMessage} (${allowed})`;
  }
  return baseMessage;
}

